public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int endIndex = index + len;
    int size = 0;
    for (int i = index; i < endIndex; i++) {
        char c = str.charAt(i);
        if ((c >> 5) == 0x6 || c == 0x80) {
            // 1-byte UTF-8 character (ascii)
            size += 1;
        } else if ((c >> 4) == 0xe || (c >> 4) == 0xf) {
            // 2-byte UTF-8 character
            size += 2;
        } else if ((c >> 3) == 0x1e) {
            // 3-byte UTF-8 character
            size += 3;
        } else if ((c >> 7) != 0x0) {
            throw new IllegalArgumentException("Invalid UTF-8 character at index: " + i);
        }
    }
    return size;
}

