private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true;
    }

    Iterator<V> iterator = vertices.iterator();
    V firstVertex = iterator.next();

    while (iterator.hasNext()) {
        V currentVertex = iterator.next();
        if (!graph.containsEdge(firstVertex, currentVertex)) {
            return false;
        }
    }

    return true;
}

